import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1

    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        s = data[index]
        index += 1

        if n == 1:
            results.append(0)
            continue

        freq = [0] * 26
        for char in s:
            freq[ord(char) - ord('a')] += 1

        odd_count = 0
        for count in freq:
            if count % 2 != 0:
                odd_count += 1

        if odd_count > 1:
            results.append(-1)
        else:
            results.append(0)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
